import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] money = new long[(int) n];
        for (int i = 0; i < money.length; i++) money[i] = Long.parseLong(next());
        long[] parent = new long[(int) m];
        for (int i = 0; i < parent.length; i++) parent[i] = Long.parseLong(next());

        int count = (int) n;
        long[] take = money.clone();
        long[] skip = new long[count];
        for (int v = count - 1; v >= 1; v--) {
            int p = (int) parent[v - 1] - 1;
            take[p] += skip[v];
            skip[p] += Math.max(take[v], skip[v]);
        }
        System.out.println(Math.max(take[0], skip[0]));
    }
}
